def find_multiple():
    # Find the LCM of 9 and 12
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    lcm_9_12 = lcm(9, 12)  # LCM of 9 and 12 is 36

    # Check which choice is a multiple of 36
    choices = [36, 15, 17, 5, 7]
    for choice in choices:
        if choice % lcm_9_12 == 0:
            return choice

    return None  # In case no choice matches (shouldn't happen here)

answer = find_multiple()
```
the answer is 36

